test('send_telegram_message does not execute shell command substitution', async () => {
  const { executeTool } = require('../src/tools/tools');
  const marker = '/tmp/pwned_marker_' + Date.now();
  await executeTool('send_telegram_message', { text: `hello $(touch ${marker})` });
  const fs = require('fs');
  assert.strictEqual(fs.existsSync(marker), false);
});

def test_lead_action_nonexistent_returns_404(client, auth_headers):
    res = client.post('/api/leads/lead_nonexistent/action', json={'action': 'delete'}, headers=auth_headers)
    assert res.status_code == 404

test('git_status includes error output when repository path is missing', async () => {
  const { executeTool } = require('../src/tools/tools');
  const res = await executeTool('git_status', { repo: 'nonexistent' });
  assert.strictEqual(res.success, false);
  assert.ok(res.error);
});

def test_login_ip_rate_limit_blocks_spraying(client):
    for i in range(35):
        client.post('/api/auth/login', json={'email': f'user{i}@test.com', 'password': 'wrongpassword'})
    res = client.post('/api/auth/login', json={'email': 'user36@test.com', 'password': 'wrongpassword'})
    assert res.status_code == 429

def test_canonical_env_is_root():
    from server.config import config
    assert config.__class__.model_config.get('env_file').endswith('/helpotron/.env')
